/****** Object:  StoredProcedure [dbo].[sp_rt_Razbivka_Postup_OtraslGroup]    Script Date: 01/01/2019 22:32:39 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
ALTER procedure [dbo].[sp_rt_Razbivka_Postup_OtraslGroup]
@SOATO nvarchar(4),
@BEGIN_DATE Datetime,
@END_DATE Datetime,
@DEPARTMENT_BASE nvarchar(255)

as 
begin 
set nocount on;

SELECT 
B.ProfsoyzNaimenovanie as OblastName,
ISNULL(ISNULL(A.BRANCH_NAME, 'Неопределен'), 'Неопределен')  as otraslName,
COUNT(A.ID) as Kolichestvo,
SUM(A.FEDERATION_AMT) as TOTALSUM,
SUM(A.OBLSOVPROF_AMT) as OBLASTSUM       
FROM KasabaKIAT_N1.dbo.tbbu_ecp_calc A
INNER JOIN KasabaKIAT_N1.dbo.tbku_StrokaProfsoyza B
ON A.OBL_DEPARTMENT_BASE = B.MATCH_DEPARTMENTBASE
WHERE CONVERT(DATE, A.OPERDATE) 
BETWEEN CONVERT(DATE, @BEGIN_DATE) AND  CONVERT(DATE, @END_DATE)
AND A.OBL_DEPARTMENT_BASE = CASE WHEN LEN(@DEPARTMENT_BASE) = 2 THEN A.OBL_DEPARTMENT_BASE
                               ELSE @DEPARTMENT_BASE END
AND A.SOATO LIKE @SOATO + '%'
GROUP BY B.ProfsoyzNaimenovanie, A.BRANCH_NAME
  
end



